import { createAreaExplorer } from './area-explorer.js';
import { INTEGRATION_AREA_POSITIVE_FUNCTIONS } from './integration-area-model.js';
import { YEAR13_AREA_CASES } from './year13-areas-data.js';
const ids=new Set(['construction-visual','top-minus-bottom','split-when-needed','geometry-or-calculus','full-toolkit','signed-vs-geometric'].map(s=>`activity:y13:integration:areas:understand:${s}`));
const el=(d,n,c='',t='')=>{const x=d.createElement(n);if(c)x.className=c;if(t)x.textContent=t;return x;};
export class Year13AreasUnderstandExperience{
 constructor(host){this.host=host;this.document=host.ownerDocument||document;this.explorers=[];} supports(id){return ids.has(id);} destroy(){this.explorers.forEach(x=>x.destroy());this.explorers=[];this.host.replaceChildren();this.host.classList.remove('year13-areas');}
 render(id){if(!this.supports(id))return false;this.destroy();this.host.classList.add('year13-areas');const slug=id.split(':').at(-1);this.renderPanel(slug);return true;}
 renderPanel(slug){const titles={ 'construction-visual':'Build the region before doing calculus','top-minus-bottom':'Top minus bottom is a construction rule','split-when-needed':'Split whenever the order changes','geometry-or-calculus':'Geometry can sometimes replace integration','full-toolkit':'Choose the integration technique last','signed-vs-geometric':'Signed integral is not always geometrical area'};const p=el(this.document,'section','year13-areas__panel');const h=el(this.document,'header','year13-areas__header');h.append(el(this.document,'span','year13-areas__eyebrow','Plan 33 · Area construction'),el(this.document,'h3','',titles[slug]));p.append(h);const body=el(this.document,'div','year13-areas__body');p.append(body);this.host.append(p);
 const construction=el(this.document,'aside','year13-areas__construction');construction.innerHTML='<strong>Area construction</strong><ol><li>Identify the required region.</li><li>Find intersections / limits.</li><li>Decide top and bottom.</li><li>Split if that order changes.</li><li>Ask whether geometry is simpler.</li><li>Only now choose an integration method.</li></ol>';body.append(construction);
 if(slug==='construction-visual'||slug==='top-minus-bottom'||slug==='split-when-needed'){const grids=el(this.document,'div','year13-areas__explorers');const a=el(this.document,'div'),b=el(this.document,'div');grids.append(a,b);body.append(grids);const exA=createAreaExplorer(a,{functions:INTEGRATION_AREA_POSITIVE_FUNCTIONS,initialFunctionId:'integration-area-bowl',initialLower:0,initialUpper:3,showFunctionSelector:false,showSplitControls:slug==='split-when-needed',showLegend:false,showAdvancedReadout:false,title:'Area under A'});const exB=createAreaExplorer(b,{functions:INTEGRATION_AREA_POSITIVE_FUNCTIONS,initialFunctionId:'integration-area-linear',initialLower:0,initialUpper:3,showFunctionSelector:false,showSplitControls:slug==='split-when-needed',showLegend:false,showAdvancedReadout:false,title:'Area under B'});this.explorers.push(exA,exB);body.append(el(this.document,'div','year13-areas__equation','Required area = area under A − area under B = ∫(A − B) dx. If A and B swap order, split first.'));return;}
 if(slug==='geometry-or-calculus'){body.append(el(this.document,'div','year13-areas__cards',''));const host=body.lastChild;for(const c of YEAR13_AREA_CASES.filter(x=>x.geometry||x.id==='line-curve')){const card=el(this.document,'article','year13-areas__card');card.append(el(this.document,'strong','',c.id==='geometry-line'?'Straight-sided region':'Curved boundary'),el(this.document,'p','',c.geometry?'Use exact geometry when it is genuinely shorter.':'Use top-minus-bottom integration when a curved boundary prevents a simpler geometry route.'));host.append(card);}return;}
 if(slug==='full-toolkit'){const rail=el(this.document,'div','year13-areas__method-grid');for(const c of YEAR13_AREA_CASES.filter(x=>!x.geometry).slice(0,7)){const card=el(this.document,'article','year13-areas__card');card.append(el(this.document,'strong','',c.method),el(this.document,'p','',c.setup));rail.append(card);}body.append(rail);return;}
 body.append(el(this.document,'div','year13-areas__equation','A definite integral is signed. Geometrical area is non-negative: split into constant-sign regions and add magnitudes where required.'));
 }
}
export function createYear13AreasUnderstandExperience(host){return new Year13AreasUnderstandExperience(host);}
